INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:claude-code:cli-surface-v1','project_tool','seed://claude-code/cli-surface','Claude Code command surface','Snapshot date: 2026-07-15. Commands and tools: /help, /clear, /compact, /config, /hooks, /mcp, /memory, /permissions, /model, /status, /doctor, /init, /review, /pr-comments, /ide, /vim, /terminal-setup. Configuration model: ~/.claude/settings.json, ~/.claude/settings.local.json, ~/.claude.json; hooks and MCP are configured in settings. Source: docs/CLAUDE_CODE_COMMAND_MATRIX_CANONICAL.md.','docs/CLAUDE_CODE_COMMAND_MATRIX_CANONICAL.md','b4dd9b8aa9dc7180e7682b1a50d8e2291f1682a395c7278810bffa596bfda0e3','claude-code,cli,command-surface,provenance',2.2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:claude-code:config-model-v1','project_doc','seed://claude-code/config-model','Claude Code command surface configuration model','Snapshot date: 2026-07-15. Canonical configuration paths: ~/.claude/settings.json, ~/.claude/settings.local.json, ~/.claude.json; hooks and MCP are configured in settings. Registration is additive, idempotent, and must preserve user-owned keys, hooks, rules, and MCP servers. Source: docs/CLAUDE_CODE_COMMAND_MATRIX_CANONICAL.md.','docs/CLAUDE_CODE_COMMAND_MATRIX_CANONICAL.md','b9f75006f677743ab6630a9deb9e498e27ab3792bf5e834e04614674da8da887','claude-code,config,mcp,rules',2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:claude-code:integration-points-v1','project_doc','seed://claude-code/integration','Claude Code command surface Simplicio integration points','Snapshot date: 2026-07-15. T4 hooks and T2 MCP/rules; Simplicio must preserve user hooks and use the canonical agent gateway. Simplicio execution remains the governed control plane; provider surfaces are compatibility inputs, not alternate mutation paths. Source: docs/CLAUDE_CODE_COMMAND_MATRIX_CANONICAL.md.','docs/CLAUDE_CODE_COMMAND_MATRIX_CANONICAL.md','49c8a39b60a5b922918a3a4c3f98f89f65e4e9303680535f510771de01467e6f','claude-code,simplicio,integration,governance',2);
